{"version":3,"file":"nav_menu.min.css","mappings":"AACA,kCACI,gBAGJ,cACI,kBACA,aACA,gBAEA,wBACI,gBACA,MACA,OACA,gEAEA,oCACI,eAKZ,0CACI,2BAEJ,oCACI,iDAEJ,wBACI,eACA,MACA,WACA,uDAGJ,sBACI,KACI,4BAEJ,GACI,yBAMR,YACI,WACA,iBACA,iBACA,kBACA,aACA,8BACA,mBACA,eACA,SACA,2BACI,WAEJ,uBACI,WAEJ,4BACI,WAEJ,oFACI,iBAEA,6FACI,aACA,mBACA,SAKZ,oBACI,oBACA,mBACA,SACA,iBACA,WAKA,yBACI,yBACA,mBACA,aACA,yBACA,gBACA,0EAEA,wDAEI,wDAIJ,oQAOI,kBAGJ,yDACI,oBAMZ,aACI,eACA,qBACA,aACA,kBACA,WAGJ,cACE,UACA,kBACA,oBACA,eACA,QACA,cACA,aACA,mBACA,uBACA,kBACA,sBACE,UACA,mBACA,oBACA,kCACE,UACA,mBACA,eAGJ,yBACE,gCACA,kBACA,QACA,eACA,oBAEF,iCACE,oBAIJ,YACE,qBACA,UACA,kBACA,kBACA,sBACA,2BACA,eAEA,0BACE,kBACA,SACA,qBACA,gCACA,eACA,oBACA,mBACA,uBACA,WACA,YACA,UACA,sBACA,kBACA,+BACA,WACA,gBACA,eACA,cACA,0EAEA,0DAEE,cACA,UACA,WACA,eAGF,gEAEE,aACA,gBAIJ,0BACE,eACA,qBACA,YACA,gBACA,oBACA,kBACA,4BACA,4BAGA,0BACI,WACA,YACA,kBACA,4BACA,iBACA,eACA,yBAMJ,aACI,aACA,SACA,gBACA,SACA,UAEA,gBACI,kBAEA,kBACI,cACA,eACA,qBAKA,yCACI,oBACA,mBACA,QAGJ,iDACI,kBACA,SACA,OACA,gBACA,gBACA,gBACA,eACA,SACA,UACA,kBACA,2BACA,yBACA,uCACA,cACA,YAKA,+GACI,UACA,mBACA,wBAOZ,0BACI,kBACA,gBAEA,4BACI,aACA,mBACA,8BACA,QACA,iBACA,qBACA,mBAEA,kCACI,mBAKJ,2DACI,kBACA,MACA,UACA,gBACA,gBACA,gBACA,eACA,SACA,UACA,kBACA,0BACA,yBACA,uCACA,cACA,YAKA,mIACI,UACA,mBACA,wBAS5B,oBACI,oBACA,mBACA,uBACA,cACA,cACA,kBACA,MACA,yEAEA,8CAEI,cACA,UACA,WACA,kBACA,wCAKJ,eACI,WACA,yBACA,eACA,kBACA,aACA,qBACA,oBACA,mBAIR,YACI,aACA,mBACA,SAIA,uCACI,aACA,mBACA,8BACA,SAGJ,8CACI,aACA,mBACA,UACA,YACA,cAEA,yDACI,cAGJ,6DACI,cACA,YAIR,uCACI,iBACA,cAGJ,+CACI,cAIR,sCACI,YACI,aAEJ,aACI,aAGA,oFAGI,aAGR,oCACI,2BACA,cAEJ,iFAEI,aAGA,8CACI,MAEA,6DACI,aAIR,+CACI,kBAMZ,oBACI,aACA,mBACA,uBACA,yBACA,mBACA,kBACA,yBACA,gBACA,eACA,cACA,cAEA,8CAEI,cACA,UACA,WACA,eAIR,0BACI,eACA,cAGJ,mBACI,eACA,MACA,QACA,SACA,YACA,eACA,gBACA,uCACA,cACA,2BACA,8BACA,aACA,sBACA,aACA,cAGJ,2BACI,wBAGJ,2BACI,aACA,mBACA,SACA,mBAGJ,yBACI,cACA,YAEA,6BACI,cACA,gBACA,YAIR,4BACI,oBACA,mBACA,QACA,iBAGJ,mBACI,oBACA,mBACA,uBACA,SACA,+BACA,gBACA,eACA,eACA,cACA,cACA,YACA,kBACA,oDAEA,4CAEI,cACA,UACA,WAGJ,kDAEI,+BACA,aACA,gBAIR,yBACI,cAIA,wCACI,aACA,sBACA,oBACA,MACA,gBACA,SACA,UAEA,2CACI,kBACA,WAEA,6CACI,aACA,mBACA,8BACA,eACA,qBACA,cACA,wCAIA,2EACI,aAGJ,+FACI,yBAGJ,4EACI,gBACA,YACA,WACA,UACA,mBACA,eACA,gBACA,yBACA,mBACA,SACA,aAGJ,mFACI,cAKZ,kDACI,gBAEA,qDACI,kBAEA,uDACI,aACA,mBACA,8BACA,QACA,eACA,qBACA,mBACA,WAIA,qFACI,aAGJ,gNAEI,yBAGJ,sFACI,gBACA,UACA,SACA,YACA,WACA,UACA,mBACA,eACA,gBACA,yBACA,mBACA,SACA,aAGJ,6FACI,cAQxB,sBACI,eACA,QACA,2BACA,cACA,SACA,UACA,SACA,aAGJ,8BACI,cAGJ,4BACI,gBAGJ,sCACI,oBACI,qBAIR,sCACI,6DAGI,yBAKR,0BACI,yBAEA,4CACI,aACA,mBACA,8BACA,SACA,WAGJ,6CACI,oBACA,mBACA,SACA,cACA,YACA,WACA,qBAEA,wDACI,oBACA,cACA,SAEA,4DACI,cACA,eACA,mBAKZ,2CACI,cACA,aACA,uBACA,YACA,iBACA,WAGI,yDACI,WACA,kBACA,eAEA,gEACI,WACA,kBACA,SACA,SACA,WACA,WACA,2BACA,+BACA,kBACA,sCAIR,8OAGI,yBAKZ,+CACI,oBACA,mBACA,SACA,cACA,cACA,WAGJ,uDACI,oBACA,mBACA,SACA,cAGJ,qDACI,oBACA,mBACA,SACA,cAGJ,+CACI,qBACA,UACA,YACA,qCACA,cAGJ,mDACI,oBACA,mBACA,uBACA,WACA,qBACA,cACA,SACA,yBACA,UACA,eACA,gBACA,2BAEA,4GAEI,cACA,cACA,kBACA,2DAGJ,yMAGI,kBAGJ,mFACI,oBAIR,kHAEI,oBACA,gBACA,qBACA,WACA,YACA,YACA,oCACA,WACA,gBACA,oBACA,mBACA,uBAEA,gPAEI,UACA,WACA,eACA,cACA,kBAIR,iDACI,oBACA,mBACA,uBACA,QACA,kBACA,mBACA,yBACA,WACA,eACA,gBACA,cACA,qBACA,mBACA,sDAEA,uDACI,oBACA,cACA,cAEA,oHAEI,cAGJ,8MAGI,kBAIR,uDACI,WAMZ,sBACI,uCACA,eACA,QACA,eACA,kBACA,oBAEA,8BACI,wBAGJ,8BACI,mBACA,oBAGJ,+BACI,kBACA,QACA,iCACA,UACA,6DAGJ,6BACI,kBACA,QACA,UACA,WACA,YACA,cACA,yBACA,WACA,yFACA,sBAGJ,yDACI,4BAGJ,0DACI,2BAGJ,wDACI,4BAGJ,2DACI,2BAGJ,6DACI,UAGJ,2DACI,0BAGJ,6BACI,kBACA,SACA,WACA,UACA,oBACA,mBACA,uBACA,WACA,YACA,UACA,SACA,kBACA,oCACA,WACA,eACA,0EAEA,gEAEI,cACA,UACA,WACA,eACA,cACA,kBAGJ,+FAEI,kBAGJ,mCACI,sBAIR,+BACI,WACA,gBACA,aACA,sBAGJ,6BACI,aACA,mBACA,uBACA,iBACA,0BACA,eACA,kBAIR,+BACI,gBAGJ,sCAEQ,2CACI,aAGJ,wLAII,aAGJ,8CACI,oBACA,WACA,iCAEA,mLAGI,kBAGJ,8EACI,oBAIR,6CACI,mBACA,WAGJ,uEACI,WACA,wCAGJ,iFACI,0BAGJ,6CACI,WAGJ,sDACI,cAKZ,wCACI,aACA,sBACA,SACA,gBACA,iBACA,wCAGJ,yBACI,oBACA,mBACA,SACA,WACA,qBACA,eACA,gBACA,gBAEA,+BACI,oBACA,mBACA,uBACA,cAEA,oEAEI,cACA,UACA,WACA,eACA,kBAKZ,8BACI,oBACA,mBACA,uBACA,QACA,kBACA,mBACA,yBACA,WACA,qBACA,eACA,gBACA,cAEA,oCACI,oBACA,cACA,cAEA,8EAEI,cACA,UACA,WACA,kB","sources":["webpack://elementor-magic-kit/./assets/src/scss/nav_menu.scss"],"sourcesContent":["//Sticky Header SCSS\r\n.elementor-widget-em_kit_nav_menu {\r\n    overflow: hidden;\r\n}\r\n\r\n.magic-header {\r\n    position: relative;\r\n    z-index: 2002;\r\n    overflow: hidden;\r\n\r\n    &.is-sticky {\r\n        position: sticky;\r\n        top: 0;\r\n        left: 0;\r\n        transition: all 0.3s ease, box-shadow 0.3s ease, background 0.3s ease;\r\n\r\n        .magic-menu {\r\n            padding: 12px 0;\r\n        }\r\n    }\r\n}\r\n/* Shadow only after scroll (class toggled via JS). !important beats theme overrides on live. */\r\n.magic-header.is-sticky:not(.is-scrolled) {\r\n    box-shadow: none !important;\r\n}\r\n.magic-header.is-sticky.is-scrolled {\r\n    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08) !important;\r\n}\r\n.magic-header.is-sticky {\r\n    position: fixed;\r\n    top: 0;\r\n    width: 100%;\r\n    animation: stickyFade 0.35s cubic-bezier(0.4,0,0.2,1);\r\n}\r\n\r\n@keyframes stickyFade {\r\n    from {\r\n        transform: translateY(-100%);\r\n    }\r\n    to {\r\n        transform: translateY(0);\r\n    }\r\n}\r\n\r\n\r\n// Navigation Menu SCSS\r\n.magic-menu{\r\n    width: 100%;\r\n    max-width: 1320px;\r\n    margin-left: auto;\r\n    margin-right: auto;\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: 20px 0;\r\n    gap: 16px;\r\n    .nav-menu-left{\r\n        z-index: 30;\r\n    }\r\n    .menu-logo{\r\n        z-index: 30;\r\n    }\r\n    .nav-menu-right{\r\n        z-index: 30;\r\n    }\r\n    .nav-menu-left,.nav-menu-right,.nav-menu-center{\r\n        overflow: visible;\r\n\r\n        > ul {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 25px;\r\n        }\r\n    }\r\n}\r\n\r\n.magic-menu-actions {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n    margin-left: auto;\r\n    z-index: 40;\r\n}\r\n\r\n//Search icon SCSS\r\n.magic-menu{\r\n    .menu-search{\r\n        border: 1px solid #121212;\r\n        border-radius: 16px;\r\n        padding: 15px;\r\n        background: transparent;\r\n        appearance: none;\r\n        transition: color 0.3s ease, background-color 0.3s ease, border-color 0.3s ease;\r\n\r\n        i,\r\n        svg {\r\n            transition: color 0.3s ease, fill 0.3s ease, stroke 0.3s ease;\r\n        }\r\n\r\n        // Uploaded SVGs often have hardcoded fill on paths — force currentColor so hover works.\r\n        svg,\r\n        svg path,\r\n        svg circle,\r\n        svg rect,\r\n        svg polygon,\r\n        svg ellipse,\r\n        svg [fill]:not([fill=\"none\"]) {\r\n            fill: currentColor;\r\n        }\r\n\r\n        svg [stroke]:not([stroke=\"none\"]) {\r\n            stroke: currentColor;\r\n        }\r\n    }\r\n}\r\n\r\n// Search popup scss\r\n.open_search {\r\n    cursor: pointer;\r\n    display: inline-block;\r\n    padding: 10px;\r\n    position: relative;\r\n    z-index: 20;\r\n}\r\n\r\n.search_block {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 99999;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  text-align: center;\r\n  &.visible{\r\n    opacity: 1;\r\n    visibility: visible;\r\n    pointer-events: auto;\r\n    .search_box {\r\n      opacity: 1;\r\n      transform: scale(1);\r\n      z-index: 100001;\r\n    }\r\n  }\r\n  .overlayer {\r\n    background-color: rgba(0, 0, 0, 0.8);\r\n    position: absolute;\r\n    inset: 0;\r\n    z-index: 100000;\r\n    pointer-events: none;\r\n  }\r\n  &.visible .overlayer {\r\n    pointer-events: auto;\r\n  }\r\n}\r\n\r\n.search_box {\r\n  display: inline-block;\r\n  opacity: 0;\r\n  position: relative;\r\n  text-align: center;\r\n  transform: scale(1.05);\r\n  transition: all 0.4s ease 0s;\r\n  z-index: 100001;\r\n  \r\n  .search_close {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: calc(50% - 60px);\r\n    transform: translate(-50%, -50%);\r\n    z-index: 100002;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 44px;\r\n    height: 44px;\r\n    padding: 0;\r\n    border: 1px solid #ffffff;\r\n    border-radius: 50%;\r\n    background-color: transparent;\r\n    color: #ffffff;\r\n    appearance: none;\r\n    cursor: pointer;\r\n    line-height: 1;\r\n    transition: background-color .2s ease, color .2s ease, border-color .2s ease;\r\n\r\n    i,\r\n    svg {\r\n      display: block;\r\n      width: 1em;\r\n      height: 1em;\r\n      font-size: 18px;\r\n    }\r\n\r\n    &:hover,\r\n    &:focus {\r\n      outline: none;\r\n      box-shadow: none;\r\n    }\r\n  }\r\n\r\n  .search_input {\r\n    font-size: 18px;\r\n    display: inline-block;\r\n    height: 60px;\r\n    max-width: 550px;\r\n    outline: medium none;\r\n    padding: 15px 20px;\r\n    transition: all 0.45s ease 0s;\r\n    border-radius: 20px 0 0 20px;\r\n  }\r\n  .inner{\r\n    button{\r\n        color: #fff;\r\n        height: 60px;\r\n        padding: 12px 24px;\r\n        border-radius: 0 20px 20px 0;\r\n        margin-left: -8px;\r\n        font-size: 18px;\r\n        background-color: #EA4E1B;\r\n    }\r\n  }\r\n}\r\n//dropdown menu scss\r\nnav {\r\n    .cnw-nav {\r\n        display: flex;\r\n        gap: 25px;\r\n        list-style: none;\r\n        margin: 0;\r\n        padding: 0;\r\n\r\n        > li {\r\n            position: relative;\r\n\r\n            > a {\r\n                display: block;\r\n                padding: 10px 0;\r\n                text-decoration: none;\r\n            }\r\n\r\n            &.menu-item-has-children {\r\n\r\n                > a {\r\n                    display: inline-flex;\r\n                    align-items: center;\r\n                    gap: 6px;\r\n                }\r\n\r\n                > .sub-menu {\r\n                    position: absolute;\r\n                    top: 100%;\r\n                    left: 0;\r\n                    min-width: 180px;\r\n                    background: #fff;\r\n                    list-style: none;\r\n                    padding: 10px 0;\r\n                    margin: 0;\r\n                    opacity: 0;\r\n                    visibility: hidden;\r\n                    transform: translateY(10px);\r\n                    transition: all .25s ease;\r\n                    box-shadow: 0 10px 25px rgba(0,0,0,.08);\r\n                    display: block;\r\n                    z-index: 100;\r\n                }\r\n\r\n                &:hover,\r\n                &.active {\r\n                    > .sub-menu {\r\n                        opacity: 1;\r\n                        visibility: visible;\r\n                        transform: translateY(0);\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        .sub-menu {\r\n            li {\r\n                position: relative;\r\n                list-style: none;\r\n\r\n                > a {\r\n                    display: flex;\r\n                    align-items: center;\r\n                    justify-content: space-between;\r\n                    gap: 8px;\r\n                    padding: 8px 15px;\r\n                    text-decoration: none;\r\n                    white-space: nowrap;\r\n\r\n                    &:hover {\r\n                        background: #f5f5f5;\r\n                    }\r\n                }\r\n\r\n                &.menu-item-has-children {\r\n                    > .sub-menu {\r\n                        position: absolute;\r\n                        top: 0;\r\n                        left: 100%;\r\n                        min-width: 180px;\r\n                        background: #fff;\r\n                        list-style: none;\r\n                        padding: 10px 0;\r\n                        margin: 0;\r\n                        opacity: 0;\r\n                        visibility: hidden;\r\n                        transform: translateX(8px);\r\n                        transition: all .25s ease;\r\n                        box-shadow: 0 10px 25px rgba(0,0,0,.08);\r\n                        display: block;\r\n                        z-index: 101;\r\n                    }\r\n\r\n                    &:hover,\r\n                    &.active {\r\n                        > .sub-menu {\r\n                            opacity: 1;\r\n                            visibility: visible;\r\n                            transform: translateX(0);\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n.magic-submenu-icon {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    line-height: 1;\r\n    flex: 0 0 auto;\r\n    position: relative;\r\n    top: 0;\r\n    transition: transform .25s ease, color .2s ease, fill .2s ease, top .2s ease;\r\n\r\n    i,\r\n    svg {\r\n        display: block;\r\n        width: 1em;\r\n        height: 1em;\r\n        font-size: inherit;\r\n        transition: color .2s ease, fill .2s ease;\r\n    }\r\n}\r\n//Layout Two Book Button scss\r\n.book-button{\r\n    a{\r\n        color: white;\r\n        background-color: #EA4E1B;\r\n        font-size: 18px;\r\n        border-radius: 4px;\r\n        padding: 12px;\r\n        text-decoration: none;\r\n        display: inline-flex;\r\n        align-items: center;\r\n    }\r\n}\r\n//Layout Three call us scss\r\n.right-side{\r\n    display: flex;\r\n    align-items: center;\r\n    gap:30px;\r\n}\r\n\r\n.magic-header-layout-three {\r\n    .magic-menu {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 24px;\r\n    }\r\n\r\n    .layout-three-left {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 100px;\r\n        min-width: 0;\r\n        flex: 1 1 auto;\r\n\r\n        .menu-logo {\r\n            flex: 0 0 auto;\r\n        }\r\n\r\n        .nav-menu-left {\r\n            flex: 0 1 auto;\r\n            min-width: 0;\r\n        }\r\n    }\r\n\r\n    .right-side {\r\n        margin-left: auto;\r\n        flex: 0 0 auto;\r\n    }\r\n\r\n    .magic-menu-actions {\r\n        margin-left: 0;\r\n    }\r\n}\r\n\r\n@media screen and (max-width: 1023px) {\r\n    .right-side{\r\n        display: none;\r\n    }\r\n    .book-button {\r\n        display: none;\r\n    }\r\n    .magic-menu {\r\n        .nav-menu-left,\r\n        .nav-menu-right,\r\n        .nav-menu-center {\r\n            display: none;\r\n        }\r\n    }\r\n    .magic-header-layout-one .mid-point {\r\n        justify-content: flex-start;\r\n        flex: 0 0 auto;\r\n    }\r\n    .magic-header-layout-one .nav-menu-left,\r\n    .magic-header-layout-one .nav-menu-right {\r\n        display: none;\r\n    }\r\n    .magic-header-layout-three {\r\n        .layout-three-left {\r\n            gap: 0;\r\n\r\n            .nav-menu-left {\r\n                display: none;\r\n            }\r\n        }\r\n\r\n        .magic-menu-actions {\r\n            margin-left: auto;\r\n        }\r\n    }\r\n}\r\n\r\n// Mobile menu\r\n.mobile-menu-toggle {\r\n    display: none;\r\n    align-items: center;\r\n    justify-content: center;\r\n    border: 1px solid #121212;\r\n    border-radius: 12px;\r\n    padding: 10px 12px;\r\n    background: transparent;\r\n    appearance: none;\r\n    cursor: pointer;\r\n    line-height: 1;\r\n    color: #121212;\r\n\r\n    i,\r\n    svg {\r\n        display: block;\r\n        width: 1em;\r\n        height: 1em;\r\n        font-size: 22px;\r\n    }\r\n}\r\n\r\n.mobile-menu-toggle__icon {\r\n    font-size: 22px;\r\n    line-height: 1;\r\n}\r\n\r\n.mobile-menu-panel {\r\n    position: fixed;\r\n    top: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    width: 320px;\r\n    max-width: 88vw;\r\n    background: #fff;\r\n    box-shadow: -8px 0 30px rgba(0, 0, 0, 0.16);\r\n    z-index: 10050;\r\n    transform: translateX(105%);\r\n    transition: transform .3s ease;\r\n    display: flex;\r\n    flex-direction: column;\r\n    padding: 20px;\r\n    overflow: auto;\r\n}\r\n\r\n.mobile-menu-panel.is-open {\r\n    transform: translateX(0);\r\n}\r\n\r\n.mobile-menu-panel__header {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n    margin-bottom: 24px;\r\n}\r\n\r\n.mobile-menu-panel__logo {\r\n    flex: 1 1 auto;\r\n    min-width: 0;\r\n\r\n    img {\r\n        display: block;\r\n        max-width: 140px;\r\n        height: auto;\r\n    }\r\n}\r\n\r\n.mobile-menu-panel__actions {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    margin-left: auto;\r\n}\r\n\r\n.mobile-menu-close {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    border: 0;\r\n    background-color: transparent;\r\n    appearance: none;\r\n    cursor: pointer;\r\n    font-size: 24px;\r\n    line-height: 1;\r\n    color: #121212;\r\n    padding: 4px;\r\n    border-radius: 6px;\r\n    transition: background-color .2s ease, color .2s ease;\r\n\r\n    i,\r\n    svg {\r\n        display: block;\r\n        width: 1em;\r\n        height: 1em;\r\n    }\r\n\r\n    &:hover,\r\n    &:focus {\r\n        background-color: transparent;\r\n        outline: none;\r\n        box-shadow: none;\r\n    }\r\n}\r\n\r\n.mobile-menu-panel__body {\r\n    flex: 1 1 auto;\r\n}\r\n\r\n.mobile-menu-panel__nav {\r\n    .cnw-nav-mobile {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: stretch;\r\n        gap: 0;\r\n        list-style: none;\r\n        margin: 0;\r\n        padding: 0;\r\n\r\n        > li {\r\n            position: relative;\r\n            width: 100%;\r\n\r\n            > a {\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: space-between;\r\n                padding: 12px 0;\r\n                text-decoration: none;\r\n                color: #121212;\r\n                border-bottom: 1px solid rgba(0, 0, 0, 0.06);\r\n            }\r\n\r\n            &.menu-item-has-children {\r\n                > a::after {\r\n                    content: none;\r\n                }\r\n\r\n                &.active > a > .magic-submenu-icon {\r\n                    transform: rotate(180deg);\r\n                }\r\n\r\n                > .sub-menu {\r\n                    position: static;\r\n                    min-width: 0;\r\n                    width: 100%;\r\n                    opacity: 1;\r\n                    visibility: visible;\r\n                    transform: none;\r\n                    box-shadow: none;\r\n                    background: transparent;\r\n                    padding: 0 0 0 14px;\r\n                    margin: 0;\r\n                    display: none;\r\n                }\r\n\r\n                &.active > .sub-menu {\r\n                    display: block;\r\n                }\r\n            }\r\n        }\r\n\r\n        .sub-menu {\r\n            list-style: none;\r\n\r\n            li {\r\n                position: relative;\r\n\r\n                > a {\r\n                    display: flex;\r\n                    align-items: center;\r\n                    justify-content: space-between;\r\n                    gap: 8px;\r\n                    padding: 10px 0;\r\n                    text-decoration: none;\r\n                    white-space: normal;\r\n                    color: #333;\r\n                }\r\n\r\n                &.menu-item-has-children {\r\n                    > a::after {\r\n                        content: none;\r\n                    }\r\n\r\n                    &.active > .magic-submenu-icon,\r\n                    &.active > a > .magic-submenu-icon {\r\n                        transform: rotate(180deg);\r\n                    }\r\n\r\n                    > .sub-menu {\r\n                        position: static;\r\n                        left: auto;\r\n                        top: auto;\r\n                        min-width: 0;\r\n                        width: 100%;\r\n                        opacity: 1;\r\n                        visibility: visible;\r\n                        transform: none;\r\n                        box-shadow: none;\r\n                        background: transparent;\r\n                        padding: 0 0 0 14px;\r\n                        margin: 0;\r\n                        display: none;\r\n                    }\r\n\r\n                    &.active > .sub-menu {\r\n                        display: block;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n.mobile-menu-backdrop {\r\n    position: fixed;\r\n    inset: 0;\r\n    background: rgba(0, 0, 0, 0.45);\r\n    z-index: 10040;\r\n    border: 0;\r\n    padding: 0;\r\n    margin: 0;\r\n    display: none;\r\n}\r\n\r\n.mobile-menu-backdrop.is-open {\r\n    display: block;\r\n}\r\n\r\nbody.magic-mobile-menu-open {\r\n    overflow: hidden;\r\n}\r\n\r\n@media screen and (max-width: 1023px) {\r\n    .mobile-menu-toggle {\r\n        display: inline-flex;\r\n    }\r\n}\r\n\r\n@media screen and (min-width: 1024px) {\r\n    .mobile-menu-panel,\r\n    .mobile-menu-backdrop,\r\n    .mobile-menu-toggle {\r\n        display: none !important;\r\n    }\r\n}\r\n\r\n/* ========== Layout Four ========== */\r\n.magic-header-layout-four {\r\n    background-color: #1a1a1a;\r\n\r\n    .layout-four-menu {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 24px;\r\n        width: 100%;\r\n    }\r\n\r\n    .layout-four-brand {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 12px;\r\n        flex: 0 0 auto;\r\n        min-width: 0;\r\n        z-index: 30;\r\n        text-decoration: none;\r\n\r\n        .menu-logo {\r\n            display: inline-flex;\r\n            flex: 0 0 auto;\r\n            margin: 0;\r\n\r\n            img {\r\n                display: block;\r\n                max-width: 100%;\r\n                object-fit: contain;\r\n            }\r\n        }\r\n    }\r\n\r\n    .nav-menu-center {\r\n        flex: 1 1 auto;\r\n        display: flex;\r\n        justify-content: center;\r\n        min-width: 0;\r\n        overflow: visible;\r\n        z-index: 30;\r\n\r\n        .cnw-nav {\r\n            > li > a {\r\n                color: #fff;\r\n                position: relative;\r\n                padding: 10px 0;\r\n\r\n                &::after {\r\n                    content: '';\r\n                    position: absolute;\r\n                    left: 50%;\r\n                    bottom: 0;\r\n                    width: 18px;\r\n                    height: 3px;\r\n                    transform: translateX(-50%);\r\n                    background-color: transparent;\r\n                    border-radius: 2px;\r\n                    transition: background-color 0.25s ease;\r\n                }\r\n            }\r\n\r\n            > li.current-menu-item > a::after,\r\n            > li.current-menu-ancestor > a::after,\r\n            > li:hover > a::after {\r\n                background-color: #E50914;\r\n            }\r\n        }\r\n    }\r\n\r\n    .layout-four-actions {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 16px;\r\n        flex: 0 0 auto;\r\n        margin-left: 0;\r\n        z-index: 40;\r\n    }\r\n\r\n    .layout-four-actions-cluster {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 16px;\r\n        flex: 0 0 auto;\r\n    }\r\n\r\n    .layout-four-actions-group {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 16px;\r\n        flex: 0 0 auto;\r\n    }\r\n\r\n    .layout-four-divider {\r\n        display: inline-block;\r\n        width: 1px;\r\n        height: 24px;\r\n        background-color: rgba(255, 255, 255, 0.25);\r\n        flex: 0 0 auto;\r\n    }\r\n\r\n    .layout-four-action-icon {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        color: #fff;\r\n        text-decoration: none;\r\n        line-height: 1;\r\n        border: 0;\r\n        background: transparent;\r\n        padding: 0;\r\n        cursor: pointer;\r\n        appearance: none;\r\n        transition: color 0.25s ease;\r\n\r\n        i,\r\n        svg {\r\n            display: block;\r\n            color: inherit;\r\n            fill: currentColor;\r\n            transition: color 0.25s ease, fill 0.25s ease, stroke 0.25s ease;\r\n        }\r\n\r\n        svg path,\r\n        svg circle,\r\n        svg [fill]:not([fill=\"none\"]) {\r\n            fill: currentColor;\r\n        }\r\n\r\n        svg [stroke]:not([stroke=\"none\"]) {\r\n            stroke: currentColor;\r\n        }\r\n    }\r\n\r\n    .menu-search.layout-four-action-icon,\r\n    .menu-search.open_search {\r\n        border: 0 !important;\r\n        border-radius: 0;\r\n        padding: 0 !important;\r\n        width: auto;\r\n        height: auto;\r\n        min-width: 0;\r\n        background: transparent !important;\r\n        color: #fff;\r\n        box-shadow: none;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n\r\n        svg,\r\n        i {\r\n            width: 1em;\r\n            height: 1em;\r\n            font-size: 18px;\r\n            color: inherit;\r\n            fill: currentColor;\r\n        }\r\n    }\r\n\r\n    .layout-four-subscribe {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 8px;\r\n        padding: 10px 20px;\r\n        border-radius: 50px;\r\n        background-color: #E50914;\r\n        color: #fff;\r\n        font-size: 14px;\r\n        font-weight: 600;\r\n        line-height: 1;\r\n        text-decoration: none;\r\n        white-space: nowrap;\r\n        transition: background-color 0.25s ease, color 0.25s ease;\r\n\r\n        &__icon {\r\n            display: inline-flex;\r\n            color: #F5C518;\r\n            line-height: 1;\r\n\r\n            i,\r\n            svg {\r\n                display: block;\r\n            }\r\n\r\n            svg,\r\n            svg path,\r\n            svg [fill]:not([fill=\"none\"]) {\r\n                fill: currentColor;\r\n            }\r\n        }\r\n\r\n        &:hover {\r\n            color: #fff;\r\n        }\r\n    }\r\n}\r\n\r\n/* Apps side offcanvas */\r\n.magic-apps-offcanvas {\r\n    --magic-apps-offcanvas-duration: 450ms;\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 999999;\r\n    visibility: hidden;\r\n    pointer-events: none;\r\n\r\n    &[hidden] {\r\n        display: none !important;\r\n    }\r\n\r\n    &.is-open {\r\n        visibility: visible;\r\n        pointer-events: auto;\r\n    }\r\n\r\n    &__overlay {\r\n        position: absolute;\r\n        inset: 0;\r\n        background-color: rgba(0, 0, 0, 0.65);\r\n        opacity: 0;\r\n        transition: opacity var(--magic-apps-offcanvas-duration) ease;\r\n    }\r\n\r\n    &__panel {\r\n        position: absolute;\r\n        inset: 0;\r\n        z-index: 1;\r\n        width: 100%;\r\n        height: 100%;\r\n        overflow: auto;\r\n        background-color: #0f0f0f;\r\n        color: #fff;\r\n        transition: transform var(--magic-apps-offcanvas-duration) cubic-bezier(0.22, 1, 0.36, 1);\r\n        will-change: transform;\r\n    }\r\n\r\n    &--left .magic-apps-offcanvas__panel {\r\n        transform: translateX(-105%);\r\n    }\r\n\r\n    &--right .magic-apps-offcanvas__panel {\r\n        transform: translateX(105%);\r\n    }\r\n\r\n    &--top .magic-a