t-four-divider,\r\n        .layout-four-user,\r\n        .layout-four-apps,\r\n        .layout-four-subscribe {\r\n            display: none;\r\n        }\r\n\r\n        .mobile-menu-toggle {\r\n            display: inline-flex;\r\n            color: #ffffff;\r\n            border-color: rgba(255, 255, 255, 0.35);\r\n\r\n            svg,\r\n            svg path,\r\n            svg [fill]:not([fill=\"none\"]) {\r\n                fill: currentColor;\r\n            }\r\n\r\n            svg [stroke]:not([stroke=\"none\"]) {\r\n                stroke: currentColor;\r\n            }\r\n        }\r\n\r\n        .mobile-menu-panel {\r\n            background: #1a1a1a;\r\n            color: #ffffff;\r\n        }\r\n\r\n        .mobile-menu-panel__nav .cnw-nav-mobile > li > a {\r\n            color: #ffffff;\r\n            border-bottom-color: rgba(255, 255, 255, 0.08);\r\n        }\r\n\r\n        .mobile-menu-panel__nav .cnw-nav-mobile .sub-menu li > a {\r\n            color: rgba(255, 255, 255, 0.75);\r\n        }\r\n\r\n        .mobile-menu-close {\r\n            color: #ffffff;\r\n        }\r\n\r\n        .mobile-menu-panel__actions {\r\n            display: none;\r\n        }\r\n    }\r\n}\r\n\r\n.mobile-menu-panel__layout-four-actions {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 12px;\r\n    margin-top: 24px;\r\n    padding-top: 20px;\r\n    border-top: 1px solid rgba(255, 255, 255, 0.1);\r\n}\r\n\r\n.mobile-layout-four-link {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    color: #ffffff;\r\n    text-decoration: none;\r\n    font-size: 15px;\r\n    font-weight: 500;\r\n    line-height: 1.2;\r\n\r\n    &__icon {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        line-height: 1;\r\n\r\n        i,\r\n        svg {\r\n            display: block;\r\n            width: 1em;\r\n            height: 1em;\r\n            font-size: 16px;\r\n            fill: curre