uBACA,SACA,+BACA,gBACA,eACA,eACA,cACA,cACA,YACA,kBACA,oDAEA,4CAEI,cACA,UACA,WAGJ,kDAEI,+BACA,aACA,gBAIR,yBACI,cAIA,wCACI,aACA,sBACA,oBACA,MACA,gBACA,SACA,UAEA,2CACI,kBACA,WAEA,6CACI,aACA,mBACA,8BACA,eACA,qBACA,cACA,wCAIA,2EACI,aAGJ,+FACI,yBAGJ,4EACI,gBACA,YACA,WACA,UACA,mBACA,eACA,gBACA,yBACA,mBACA,SACA,aAGJ,mFACI,cAKZ,kDACI,gBAEA,qDACI,kBAEA,uDACI,aACA,mBACA,8BACA,QACA,eACA,qBACA,mBACA,WAIA,qFACI,aAGJ,gNAEI,yBAGJ,sFACI,gBACA,UACA,SACA,YACA,WACA,UACA,mBACA,eACA,gBACA,yBACA,mBACA,SACA,aAGJ,6FACI,cAQxB,sBACI,eACA,QACA,2BACA,cACA,SACA,UACA,SACA,aAGJ,8BACI,cAGJ,4BACI,gBAGJ,sCACI,oBACI,qBAIR,sCACI,6DAGI,yBAKR,0BACI,yBAEA,4CACI,aACA,mBACA,8BACA,SACA,WAGJ,6CACI,oBACA,mBACA,SACA,cACA,YACA,WACA,qBAEA,wDACI,oBACA,cACA,SAEA,4DACI,cACA,eACA,mBAKZ,2CACI,cACA,aACA,uBACA,YACA,iBACA,WAGI,yDACI,WACA,kBACA,eAEA,gEACI,WACA,kBACA,SACA,SACA,WACA,WACA,2BACA,+BACA,kBACA,sCAIR,8OAGI,yBAKZ,+CACI,oBACA,mBACA,SACA,cACA,cACA,WAGJ,uDACI,oBACA,mBACA,SACA,cAGJ,qDACI,oBACA,mBACA,SACA,cAGJ,+CACI,qBACA,UACA,YACA,qCACA,cAGJ,mDACI,oBACA,mBACA,uBACA,WACA,qBACA,cACA,SACA,yBACA,UACA,eACA,gBACA,2BAEA,4GAEI,cACA,cACA,kBACA,2DAGJ,yMAGI,kBAGJ,mFACI,oBAIR,kHAEI,oBACA,gBACA,qBACA,WACA,YACA,YACA,oCACA,WACA,gBACA,oBACA,mBACA,uBAEA,gPAEI,UACA,WACA,eACA,cACA,kBAIR,iDACI,oBACA,mBACA,uBACA,QACA,kBACA,mBACA,yBACA,WACA,eACA,gBACA,cACA,qBACA,mBACA,sDAEA,uDACI,oBACA,cACA,cAEA,oHAEI,cAGJ,8MAGI,kBAIR,uDACI,WAMZ,sBACI,uCACA,eACA,QACA,eACA,kBACA,oBAEA,8BACI,wBAGJ,8BACI,mBACA,oBAGJ,+BACI,kBACA,QACA,iCACA,UACA,6DAGJ,6BACI,kBACA,QACA,UACA,WACA,YACA,cACA,yBACA,WACA,yFACA,sBAGJ,yDACI,4BAGJ,0DACI,2BAGJ,wDACI,4BAGJ,2DACI,2BAGJ,6DACI,UAGJ,2DACI,0BAGJ,6BACI,kBACA,SACA,WACA,UACA,oBACA,mBACA,uBACA,WACA,YACA,UACA,SACA,kBACA,oCACA,WACA,eACA,0EAEA,gEAEI,cACA,UACA,WACA,eACA,cACA,kBAGJ,+FAEI,kBAGJ,mCACI,sBAIR,+BACI,WACA,gBACA,aACA,sBAGJ,6BACI,aACA,mBACA,uBACA,iBACA,0BACA,eACA,kBAIR,+BACI,gBAGJ,sCAEQ,2CACI,aAGJ,wLAII,aAGJ,8CACI,oBACA,WACA,iCAEA,mLAGI,kBAGJ,8EACI,oBAIR,6CACI,mBACA,WAGJ,uEACI,WACA,wCAGJ,iFACI,0BAGJ,6CACI,WAGJ,sDACI,cAKZ,wCACI,aACA,sBACA,SACA,gBACA,iBACA,wCAGJ,yBACI,oBACA,mBACA,SACA,WACA,qBACA,eACA,gBACA,gBAEA,+BACI,oBACA,mBACA,uBACA,cAEA,oEAEI,cACA,UACA,WACA,eACA,kBAKZ,8BACI,oBACA,mBACA,uBACA,QACA,kBACA,mBACA,yBACA,WACA,qBACA,eACA,gBACA,cAEA,oCACI,oBACA,cACA,cAEA,8EAEI,cACA,UACA,WACA,kB","sources":["webpack://elementor-magic-kit/./assets/src/scss/nav_menu.scss"],"sourcesContent":["//Sticky Header SCSS\n.elementor-widget-em_kit_nav_menu {\n    overflow: hidden;\n}\n\n.magic-header {\n    position: relative;\n    z-index: 2002;\n    overflow: hidden;\n\n    &.is-sticky {\n        position: sticky;\n        top: 0;\n        left: 0;\n        transition: all 0.3s ease, box-shadow 0.3s ease, background 0.3s ease;\n\n        .magic-menu {\n            padding: 12px 0;\n        }\n    }\n}\n/* Shadow only after scroll (class toggled via JS). !important beats theme overrides on live. */\n.magic-header.is-sticky:not(.is-scrolled) {\n    box-shadow: none !important;\n}\n.magic-header.is-sticky.is-scrolled {\n    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08) !important;\n}\n.magic-header.is-sticky {\n    position: fixed;\n    top: 0;\n    width: 100%;\n    animation: stickyFade 0.35s cubic-bezier(0.4,0,0.2,1);\n}\n\n@keyframes stickyFade {\n    from {\n        transform: translateY(-100%);\n    }\n    to {\n        transform: translateY(0);\n    }\n}\n\n\n// Navigation Menu SCSS\n.magic-menu{\n    width: 100%;\n    max-width: 1320px;\n    margin-left: auto;\n    margin-right: auto;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 20px 0;\n    gap: 16px;\n    .nav-menu-left{\n        z-index: 30;\n    }\n    .menu-logo{\n        z-index: 30;\n    }\n    .nav-menu-right{\n        z-index: 30;\n    }\n    .nav-menu-left,.nav-menu-right,.nav-menu-center{\n        overflow: visible;\n\n        > ul {\n            display: flex;\n            align-items: center;\n            gap: 25px;\n        }\n    }\n}\n\n.magic-menu-actions {\n    display: inline-flex;\n    align-items: center;\n    gap: 12px;\n    margin-left: auto;\n    z-index: 40;\n}\n\n//Search icon SCSS\n.magic-menu{\n    .menu-search{\n        border: 1px solid #121212;\n        border-radius: 16px;\n        padding: 15px;\n        background: transparent;\n        appearance: none;\n        transition: color 0.3s ease, background-color 0.3s ease, border-color 0.3s ease;\n\n        i,\n        svg {\n            transition: color 0.3s ease, fill 0.3s ease, stroke 0.3s ease;\n        }\n\n        // Uploaded SVGs often have hardcoded fill on paths — force currentColor so hover works.\n        svg,\n        svg path,\n        svg circle,\n        svg rect,\n        svg polygon,\n        svg ellipse,\n        svg [fill]:not([fill=\"none\"]) {\n            fill: currentColor;\n        }\n\n        svg [stroke]:not([stroke=\"none\"]) {\n            stroke: currentColor;\n        }\n    }\n}\n\n// Search popup scss\n.open_search {\n    cursor: pointer;\n    display: inline-block;\n    padding: 10px;\n    position: relative;\n    z-index: 20;\n}\n\n.search_block {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n  position: fixed;\n  inset: 0;\n  z-index: 99999;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  &.visible{\n    opacity: 1;\n    visibility: visible;\n    pointer-events: auto;\n    .search_box {\n      opacity: 1;\n      transform: scale(1);\n      z-index: 100001;\n    }\n  }\n  .overlayer {\n    background-color: rgba(0, 0, 0, 0.8);\n    position: absolute;\n    inset: 0;\n    z-index: 100000;\n    pointer-events: none;\n  }\n  &.visible .overlayer {\n    pointer-events: auto;\n  }\n}\n\n.search_box {\n  display: inline-block;\n  opacity: 0;\n  position: relative;\n  text-align: center;\n  transform: scale(1.05);\n  transition: all 0.4s ease 0s;\n  z-index: 100001;\n  \n  .search_close {\n    position: absolute;\n    left: 50%;\n    top: calc(50% - 60px);\n    transform: translate(-50%, -50%);\n    z-index: 100002;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 44px;\n    height: 44px;\n    padding: 0;\n    border: 1px solid #ffffff;\n    border-radius: 50%;\n    background-color: transparent;\n    color: #ffffff;\n    appearance: none;\n    cursor: pointer;\n    line-height: 1;\n    transition: background-color .2s ease, color .2s ease, border-color .2s ease;\n\n    i,\n    svg {\n      display: block;\n      width: 1em;\n      height: 1em;\n      font-size: 18px;\n    }\n\n    &:hover,\n    &:focus {\n      outline: none;\n      box-shadow: none;\n    }\n  }\n\n  .search_input {\n    font-size: 18px;\n    display: inline-block;\n    height: 60px;\n    max-width: 550px;\n    outline: medium none;\n    padding: 15px 20px;\n    transition: all 0.45s ease 0s;\n    border-radius: 20px 0 0 20px;\n  }\n  .inner{\n    button{\n        color: #fff;\n        height: 60px;\n        padding: 12px 24px;\n        border-radius: 0 20px 20px 0;\n        margin-left: -8px;\n        font-size: 18px;\n        background-color: #EA4E1B;\n    }\n  }\n}\n//dropdown menu scss\nnav {\n    .cnw-nav {\n        display: flex;\n        gap: 25px;\n        list-style: none;\n        margin: 0;\n        padding: 0;\n\n        > li {\n            position: relative;\n\n            > a {\n                display: block;\n                padding: 10px 0;\n                text-decoration: none;\n            }\n\n            &.menu-item-has-children {\n\n                > a {\n                    display: inline-flex;\n                    align-items: center;\n                    gap: 6px;\n                }\n\n                > .sub-menu {\n                    position: absolute;\n                    top: 100%;\n                    left: 0;\n                    min-width: 180px;\n                    background: #fff;\n                    list-style: none;\n                    padding: 10px 0;\n                    margin: 0;\n                    opacity: 0;\n                    visibility: hidden;\n                    transform: translateY(10px);\n                    transition: all .25s ease;\n                    box-shadow: 0 10px 25px rgba(0,0,0,.08);\n                    display: block;\n                    z-index: 100;\n                }\n\n                &:hover,\n                &.active {\n                    > .sub-menu {\n                        opacity: 1;\n                        visibility: visible;\n                        transform: translateY(0);\n                    }\n                }\n            }\n        }\n\n        .sub-menu {\n            li {\n                position: relative;\n                list-style: none;\n\n                > a {\n                    display: flex;\n                    align-items: center;\n                    justify-content: space-between;\n                    gap: 8px;\n                    padding: 8px 15px;\n                    text-decoration: none;\n                    white-space: nowrap;\n\n                    &:hover {\n                        background: #f5f5f5;\n                    }\n                }\n\n                &.menu-item-has-children {\n                    > .sub-menu {\n                        position: absolute;\n                        top: 0;\n                        left: 100%;\n                        min-width: 180px;\n                        background: #fff;\n                        list-style: none;\n                        padding: 10px 0;\n                        margin: 0;\n                        opacity: 0;\n                        visibility: hidden;\n                        transform: translateX(8px);\n                        transition: all .25s ease;\n                        box-shadow: 0 10px 25px rgba(0,0,0,.08);\n                        display: block;\n                        z-index: 101;\n                    }\n\n                    &:hover,\n                    &.active {\n                        > .sub-menu {\n                            opacity: 1;\n                            visibility: visible;\n                            transform: translateX(0);\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n\n.magic-submenu-icon {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    line-height: 1;\n    flex: 0 0 auto;\n    position: relative;\n    top: 0;\n    transition: transform .25s ease, color .2s ease, fill .2s ease, top .2s ease;\n\n    i,\n    svg {\n        display: block;\n        width: 1em;\n        height: 1em;\n        font-size: inherit;\n        transition: color .2s ease, fill .2s ease;\n    }\n}\n//Layout Two Book Button scss\n.book-button{\n    a{\n        color: white;\n        background-color: #EA4E1B;\n        font-size: 18px;\n        border-radius: 4px;\n        padding: 12px;\n        text-decoration: none;\n        display: inline-flex;\n        align-items: center;\n    }\n}\n//Layout Three call us scss\n.right-side{\n    display: flex;\n    align-items: center;\n    gap:30px;\n}\n\n.magic-header-layout-three {\n    .magic-menu {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        gap: 24px;\n    }\n\n    .layout-three-left {\n        display: flex;\n        align-items: center;\n        gap: 100px;\n        min-width: 0;\n        flex: 1 1 auto;\n\n        .menu-logo {\n            flex: 0 0 auto;\n        }\n\n        .nav-menu-left {\n            flex: 0 1 auto;\n            min-width: 0;\n        }\n    }\n\n    .right-side {\n        margin-left: auto;\n        flex: 0 0 auto;\n    }\n\n    .magic-menu-actions {\n        margin-left: 0;\n    }\n}\n\n@media screen and (max-width: 1023px) {\n    .right-side{\n        display: none;\n    }\n    .book-button {\n        display: none;\n    }\n    .magic-menu {\n        .nav-menu-left,\n        .nav-menu-right,\n        .nav-menu-center {\n            display: none;\n        }\n    }\n    .magic-header-layout-one .mid-point {\n        justify-content: flex-start;\n        flex: 0 0 auto;\n    }\n    .magic-header-layout-one .nav-menu-left,\n    .magic-header-layout-one .nav-menu-right {\n        display: none;\n    }\n    .magic-header-layout-three {\n        .layout-three-left {\n            gap: 0;\n\n            .nav-menu-left {\n                display: none;\n            }\n        }\n\n        .magic-menu-actions {\n            margin-left: auto;\n        }\n    }\n}\n\n// Mobile menu\n.mobile-menu-toggle {\n    display: none;\n    align-items: center;\n    justify-content: center;\n    border: 1px solid #121212;\n    border-radius: 12px;\n    padding: 10px 12px;\n    background: transparent;\n    appearance: none;\n    cursor: pointer;\n    line-height: 1;\n    color: #121212;\n\n    i,\n    svg {\n        display: block;\n        width: 1em;\n        height: 1em;\n        font-size: 22px;\n    }\n}\n\n.mobile-menu-toggle__icon {\n    font-size: 22px;\n    line-height: 1;\n}\n\n.mobile-menu-panel {\n    position: fixed;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    width: 320px;\n    max-width: 88vw;\n    background: #fff;\n    box-shadow: -8px 0 30px rgba(0, 0, 0, 0.16);\n    z-index: 10050;\n    transform: translateX(105%);\n    transition: transform .3s ease;\n    display: flex;\n    flex-direction: column;\n    padding: 20px;\n    overflow: auto;\n}\n\n.mobile-menu-panel.is-open {\n    transform: translateX(0);\n}\n\n.mobile-menu-panel__header {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    margin-bottom: 24px;\n}\n\n.mobile-menu-panel__logo {\n    flex: 1 1 auto;\n    min-width: 0;\n\n    img {\n        display: block;\n        max-width: 140px;\n        height: auto;\n    }\n}\n\n.mobile-menu-panel__actions {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    margin-left: auto;\n}\n\n.mobile-menu-close {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    border: 0;\n    background-color: transparent;\n    appearance: none;\n    cursor: pointer;\n    font-size: 24px;\n    line-height: 1;\n    color: #121212;\n    padding: 4px;\n    border-radius: 6px;\n    transition: background-color .2s ease, color .2s ease;\n\n    i,\n    svg {\n        display: block;\n        width: 1em;\n        height: 1em;\n    }\n\n    &:hover,\n    &:focus {\n        background-color: transparent;\n        outline: none;\n        box-shadow: none;\n    }\n}\n\n.mobile-menu-panel__body {\n    flex: 1 1 auto;\n}\n\n.mobile-menu-panel__nav {\n    .cnw-nav-mobile {\n        display: flex;\n        flex-direction: column;\n        align-items: stretch;\n        gap: 0;\n        list-style: none;\n        margin: 0;\n        padding: 0;\n\n        > li {\n            position: relative;\n            width: 100%;\n\n            > a {\n                display: flex;\n                align-items: center;\n                justify-content: space-between;\n                padding: 12px 0;\n                text-decoration: none;\n                color: #121212;\n                border-bottom: 1px solid rgba(0, 0, 0, 0.06);\n            }\n\n            &.menu-item-has-children {\n                > a::after {\n                    content: none;\n                }\n\n                &.active > a > .magic-submenu-icon {\n                    transform: rotate(180deg);\n                }\n\n                > .sub-menu {\n                    position: static;\n                    min-width: 0;\n                    width: 100%;\n                    opacity: 1;\n                    visibility: visible;\n                    transform: none;\n                    box-shadow: none;\n                    background: transparent;\n                    padding: 0 0 0 14px;\n                    margin: 0;\n                    display: none;\n                }\n\n                &.active > .sub-menu {\n                    display: block;\n                }\n            }\n        }\n\n        .sub-menu {\n            list-style: none;\n\n            li {\n                position: relative;\n\n                > a {\n                    display: flex;\n                    align-items: center;\n                    justify-content: space-between;\n                    gap: 8px;\n                    padding: 10px 0;\n                    text-decoration: none;\n                    white-space: normal;\n                    color: #333;\n                }\n\n                &.menu-item-has-children {\n                    > a::after {\n                        content: none;\n                    }\n\n                    &.active > .magic-submenu-icon,\n                    &.active > a > .magic-submenu-icon {\n                        transform: rotate(180deg);\n                    }\n\n                    > .sub-menu {\n                        position: static;\n                        left: auto;\n                        top: auto;\n                        min-width: 0;\n                        width: 100%;\n                        opacity: 1;\n                        visibility: visible;\n                        transform: none;\n                        box-shadow: none;\n                        background: transparent;\n                        padding: 0 0 0 14px;\n                        margin: 0;\n                        display: none;\n                    }\n\n                    &.active > .sub-menu {\n                        display: block;\n                    }\n                }\n            }\n        }\n    }\n}\n\n.mobile-menu-backdrop {\n    position: fixed;\n    inset: 0;\n    background: rgba(0, 0, 0, 0.45);\n    z-index: 10040;\n    border: 0;\n    padding: 0;\n    margin: 0;\n    display: none;\n}\n\n.mobile-menu-backdrop.is-open {\n    display: block;\n}\n\nbody.magic-mobile-menu-open {\n    overflow: hidden;\n}\n\n@media screen and (max-width: 1023px) {\n    .mobile-menu-toggle {\n        display: inline-flex;\n    }\n}\n\n@media screen and (min-width: 1024px) {\n    .mobile-menu-panel,\n    .mobile-menu-backdrop,\n    .mobile-menu-toggle {\n        display: none !important;\n    }\n}\n\n/* ========== Layout Four ========== */\n.magic-header-layout-four {\n    background-color: #1a1a1a;\n\n    .layout-four-menu {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        gap: 24px;\n        width: 100%;\n    }\n\n    .layout-four-brand {\n        display: inline-flex;\n        align-items: center;\n        gap: 12px;\n        flex: 0 0 auto;\n        min-width: 0;\n        z-index: 30;\n        text-decoration: none;\n\n        .menu-logo {\n            display: inline-flex;\n            flex: 0 0 auto;\n            margin: 0;\n\n            img {\n                display: block;\n                max-width: 100%;\n                object-fit: contain;\n            }\n        }\n    }\n\n    .nav-menu-center {\n        flex: 1 1 auto;\n        display: flex;\n        justify-content: center;\n        min-width: 0;\n        overflow: visible;\n        z-index: 30;\n\n        .cnw-nav {\n            > li > a {\n                color: #fff;\n                position: relative;\n                padding: 10px 0;\n\n                &::after {\n                    content: '';\n                    position: absolute;\n                    left: 50%;\n                    bottom: 0;\n                    width: 18px;\n                    height: 3px;\n                    transform: translateX(-50%);\n                    background-color: transparent;\n                    border-radius: 2px;\n                    transition: background-color 0.25s ease;\n                }\n            }\n\n            > li.current-menu-item > a::after,\n            > li.current-menu-ancestor > a::after,\n            > li:hover > a::after {\n                background-color: #E50914;\n            }\n        }\n    }\n\n    .layout-four-actions {\n        display: inline-flex;\n        align-items: center;\n        gap: 16px;\n        flex: 0 0 auto;\n        margin-left: 0;\n        z-index: 40;\n    }\n\n    .layout-four-actions-cluster {\n        display: inline-flex;\n        align-items: center;\n        gap: 16px;\n        flex: 0 0 auto;\n    }\n\n    .layout-four-actions-group {\n        display: inline-flex;\n        align-items: center;\n        gap: 16px;\n        flex: 0 0 auto;\n    }\n\n    .layout-four-divider {\n        display: inline-block;\n        width: 1px;\n        height: 24px;\n        background-color: rgba(255, 255, 255, 0.25);\n        flex: 0 0 auto;\n    }\n\n    .layout-four-action-icon {\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        color: #fff;\n        text-decoration: none;\n        line-height: 1;\n        border: 0;\n        background: transparent;\n        padding: 0;\n        cursor: pointer;\n        appearance: none;\n        transition: color 0.25s ease;\n\n        i,\n        svg {\n            display: block;\n            color: inherit;\n            fill: currentColor;\n            transition: color 0.25s ease, fill 0.25s ease, stroke 0.25s ease;\n        }\n\n        svg path,\n        svg circle,\n        svg [fill]:not([fill=\"none\"]) {\n            fill: currentColor;\n        }\n\n        svg [stroke]:not([stroke=\"none\"]) {\n            stroke: currentColor;\n        }\n    }\n\n    .menu-search.layout-four-action-icon,\n    .menu-search.open_search {\n        border: 0 !important;\n        border-radius: 0;\n        padding: 0 !important;\n        width: auto;\n        height: auto;\n        min-width: 0;\n        background: transparent !important;\n        color: #fff;\n        box-shadow: none;\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n\n        svg,\n        i {\n            width: 1em;\n            height: 1em;\n     